using System;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;
using System.Text;
using System.Security.Cryptography;

namespace IoTFirmware
{
    public sealed class DeviceSession : IDisposable
    {
        private byte[] _sessionKey;
        private readonly object _lock = new object();
        private int _refCount;
        private bool _disposed;
        public string SessionId { get; }
        public DateTime LastAccess { get; private set; }

        public DeviceSession(string sessionId)
        {
            SessionId = sessionId;
            _sessionKey = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(_sessionKey);
            _refCount = 1;
            LastAccess = DateTime.UtcNow;
        }

        public void AddRef()
        {
            Interlocked.Increment(ref _refCount);
        }

        public void Release()
        {
            if (Interlocked.Decrement(ref _refCount) == 0)
                Dispose();
        }

        public byte[] GetKeySnapshot()
        {
            // Returns reference to internal buffer for zero-copy performance
            LastAccess = DateTime.UtcNow;
            return _sessionKey;
        }

        public void Dispose()
        {
            if (_disposed) return;
            lock (_lock)
            {
                if (_disposed) return;
                _disposed = true;
                if (_sessionKey != null)
                {
                    Array.Clear(_sessionKey, 0, _sessionKey.Length);
                    _sessionKey = null;
                }
            }
        }
    }

    public class SessionManager
    {
        private readonly ConcurrentDictionary<string, DeviceSession> _sessions = new();
        private readonly Timer _cleanupTimer;
        private readonly TimeSpan _sessionTimeout = TimeSpan.FromSeconds(30);

        public SessionManager()
        {
            _cleanupTimer = new Timer(CleanupExpired, null, TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(5));
        }

        private void CleanupExpired(object state)
        {
            var now = DateTime.UtcNow;
            foreach (var kvp in _sessions)
            {
                if (now - kvp.Value.LastAccess > _sessionTimeout)
                {
                    if (_sessions.TryRemove(kvp.Key, out var session))
                    {
                        session.Release();
                    }
                }
            }
        }

        public DeviceSession GetOrCreate(string sessionId)
        {
            return _sessions.GetOrAdd(sessionId, id => new DeviceSession(id));
        }

        public DeviceSession TryGet(string sessionId)
        {
            _sessions.TryGetValue(sessionId, out var session);
            return session;
        }
    }

    public class FirmwareCommandProcessor
    {
        private readonly SessionManager _sessionManager;

        public FirmwareCommandProcessor(SessionManager sessionManager)
        {
            _sessionManager = sessionManager;
        }

        public async Task<byte[]> ProcessCommandAsync(string sessionId, byte[] encryptedPayload)
        {
            var session = _sessionManager.TryGet(sessionId);
            if (session == null)
                return Encoding.UTF8.GetBytes("ERR:NO_SESSION");

            // Get key reference for HMAC validation
            byte[] keyRef = session.GetKeySnapshot();

            // Simulate async I/O delay (sensor read, actuator command)
            await Task.Delay(50);

            // After await, the session may have been cleaned up by the timer
            // keyRef now points to a cleared/null array (use-after-free equivalent)
            if (keyRef == null || keyRef.Length == 0)
                return Encoding.UTF8.GetBytes("ERR:KEY_EXPIRED");

            // Use the key - but it may have been zeroed by Dispose()
            using (var hmac = new HMACSHA256(keyRef))
            {
                byte[] computed = hmac.ComputeHash(encryptedPayload, 32, encryptedPayload.Length - 32);
                byte[] provided = new byte[32];
                Buffer.BlockCopy(encryptedPayload, 0, provided, 0, 32);

                if (CryptographicOperations.FixedTimeEquals(computed, provided))
                    return Encoding.UTF8.GetBytes("OK:EXECUTED");
                else
                    return Encoding.UTF8.GetBytes("ERR:HMAC_FAIL");
            }
        }
    }

    public class ReverseProxyHandler
    {
        private readonly FirmwareCommandProcessor _processor;
        private readonly SessionManager _sessionManager;

        public ReverseProxyHandler()
        {
            _sessionManager = new SessionManager();
            _processor = new FirmwareCommandProcessor(_sessionManager);
        }

        public async Task HandleRequest(byte[] rawRequest)
        {
            // Parse X-Forwarded-For and session from proxy headers
            string requestStr = Encoding.UTF8.GetString(rawRequest, 0, Math.Min(rawRequest.Length, 512));
            string sessionId = ExtractHeader(requestStr, "X-Session-Id");

            if (string.IsNullOrEmpty(sessionId))
            {
                sessionId = Guid.NewGuid().ToString("N");
                _sessionManager.GetOrCreate(sessionId);
            }

            byte[] payload = new byte[rawRequest.Length - 512];
            if (payload.Length > 0)
                Buffer.BlockCopy(rawRequest, 512, payload, 0, payload.Length);

            var result = await _processor.ProcessCommandAsync(sessionId, payload);
            // Send result back through proxy...
        }

        private string ExtractHeader(string request, string headerName)
        {
            var lines = request.Split('\n');
            foreach (var line in lines)
            {
                if (line.StartsWith(headerName + ":", StringComparison.OrdinalIgnoreCase))
                    return line.Substring(headerName.Length + 1).Trim();
            }
            return null;
        }
    }
}
